// Check token expiration and refresh if needed
const tokens = $input.all();
const refreshedTokens = [];

for (const item of tokens) {
  const tokenData = item.json;
  const expiresAt = new Date(tokenData.expires_at);
  const now = new Date();
  const daysUntilExpiry = Math.ceil((expiresAt - now) / (1000 * 60 * 60 * 24));

  // Refresh if expires in less than 7 days
  if (daysUntilExpiry < 7) {
    refreshedTokens.push({
      app_id: tokenData.app_id,
      app_secret: tokenData.app_secret,
      current_token: tokenData.access_token,
      token_type: tokenData.token_type,
      needs_refresh: true
    });
  } else {
    console.log(`Token ${tokenData.token_type} expires in ${daysUntilExpiry} days - no refresh needed`);
  }
}

return refreshedTokens.map(token => ({ json: token }));

// Process token refresh response
const response = $input.first().json;
const originalData = $input.first().json;

if (response.statusCode === 200 && response.body.access_token) {
  const newToken = response.body.access_token;
  const expiresIn = response.body.expires_in || 5184000; // Default 60 days
  const expiresAt = new Date(Date.now() + (expiresIn * 1000));

  return [{
    json: {
      token_type: originalData.token_type,
      access_token: newToken,
      expires_at: expiresAt.toISOString(),
      refreshed_at: new Date().toISOString(),
      success: true
    }
  }];
} else {
  console.error('Token refresh failed:', response.body);
  return [{
    json: {
      token_type: originalData.token_type,
      error: response.body?.error?.message || 'Unknown error',
      success: false
    }
  }];
}

// Prepare token refresh notification
const results = $input.all();
const successful = results.filter(item => item.json.success);
const failed = results.filter(item => !item.json.success);

if (results.length === 0) {
  return [{ json: { skip: true } }];
}

let emailContent = `
<h2>🔄 Отчет об обновлении токенов Facebook API</h2>
<p>Результаты автоматического обновления токенов:</p>
`;

if (successful.length > 0) {
  emailContent += `
  <div style="background: #d4edda; padding: 15px; margin: 10px 0; border-radius: 5px; border-left: 4px solid #28a745;">
    <h3>✅ Успешно обновлено: ${successful.length}</h3>
    <ul>`;

  for (const item of successful) {
    emailContent += `<li><strong>${item.json.token_type}</strong> - обновлен ${new Date(item.json.refreshed_at).toLocaleString('ru-RU')}</li>`;
  }

  emailContent += `</ul></div>`;
}

if (failed.length > 0) {
  emailContent += `
  <div style="background: #f8d7da; padding: 15px; margin: 10px 0; border-radius: 5px; border-left: 4px solid #dc3545;">
    <h3>❌ Ошибки обновления: ${failed.length}</h3>
    <ul>`;

  for (const item of failed) {
    emailContent += `<li><strong>${item.json.token_type}</strong> - ${item.json.error}</li>`;
  }

  emailContent += `</ul></div>`;
}

emailContent += `
<hr>
<p><small>Автоматическое уведомление от системы управления токенами</small></p>
`;

return [{
  json: {
    subject: `🔄 Обновление токенов: ${successful.length} успешно, ${failed.length} ошибок`,
    html: emailContent,
    skip: results.length === 0
  }
}];
